window.LERNDATEN={"decks":[{"id":"v","name":"Puls und Blutdruck","sub":"CE 3.2 A: Vitalzeichen kontrollieren"},{"id":"w","name":"Fachwörter","sub":"Lateinisch und Griechisch auf Deutsch"},{"id":"s","name":"Berufliches Selbstverständnis","sub":"Pflege-Charta, ICN-Kodex, Kompetenzen, Maslow"},{"id":"l","name":"Lernen lernen","sub":"CE 1.2: Gedächtnis, Motivation, Lerntypen"},{"id":"k","name":"Kommunikation und Belastung","sub":"Kommunikationsmodelle, Ethik, Stress und Burnout"}],"cards":[{"id":"K000","deck":"v","q":"Was ist der Puls? (lat. Pulsus)","a":"Pulsus = Schlag / Stoß.\nDruck- und Volumenschwankung durch den Blutausstoß des Herzens während der Systole. Es entstehen Druckwellen, die ins arterielle Gefäßsystem gelangen.","kw":"Schlag; Stoß|stoss; Druck; Volumen; Herz; Systole; Arterien|arteri"},{"id":"K001","deck":"v","q":"Wo wird der Puls zentral gemessen?","a":"A. carotis (Halsschlagader)\nA. femoralis (Leistenarterie)","kw":"carotis; Halsschlagader|hals; femoralis; Leistenarterie|leiste"},{"id":"K002","deck":"v","q":"Welche peripheren Pulsmessorte gibt es?","a":"• A. temporalis (Schläfenarterie)\n• A. brachialis (Oberarmarterie)\n• A. radialis (Speichenarterie)\n• A. ulnaris (Ellenarterie)\n• A. poplitea (Kniekehlenarterie)\n• A. tibialis posterior (hintere Schienbeinarterie)\n• A. dorsalis pedis (Fußrückenarterie)","kw":"temporalis; brachialis; radialis; ulnaris; poplitea; tibialis; dorsalis"},{"id":"K003","deck":"v","q":"Wie lässt sich der Puls bestimmen?","a":"Manuell (mit den Fingern, z. B. an der A. radialis) oder elektronisch (z. B. mit einem Pulsoximeter am Finger).","kw":"manuell; elektronisch|elektron; Finger"},{"id":"K004","deck":"v","q":"Wie misst du den Puls manuell? (Ablauf)","a":"1. Pflegeempfänger sollte vorher ca. 15 Minuten Ruhe haben, damit keine falsch hohen Werte entstehen.\n2. Sitzen oder liegen, Unterarm mit leicht gebeugtem Handgelenk lagern.\n3. Kuppen von Zeige-, Mittel- und Ringfinger an die A. radialis legen (Daumenseite des Handgelenks) und leicht drücken.\n4. Mit Sekundenzeiger 1 Minute zählen – oder 15 Sekunden zählen und mal 4 rechnen.\n5. Auf Pulsqualität und Rhythmus achten.\n6. Werte dokumentieren, Pflegefachkraft informieren.","kw":"Ruhe; radialis; Zeigefinger|zeige; Mittelfinger|mittel; Ringfinger|ring; Minute|minute; mal vier|vier/4; Rhythmus; dokumentieren|dokument"},{"id":"K005","deck":"v","q":"Wann wird der Puls gemessen? (Indikationen)","a":"• Ausgangswert nicht im Normbereich\n• Veränderung anderer Vitalzeichen (Blutdruck, Atmung, Temperatur)\n• Vor der Mobilisation\n• Nach Unfällen, bei Blut- und Flüssigkeitsverlusten, im Schockzustand\n• Bei Aufnahme und regelmäßig im Krankenhausaufenthalt\n• Vor, während und nach Operationen\n• Bei Herz-/Kreislauf- und Lungenerkrankungen, Fieber, Vergiftungen\n• Bei kreislaufwirksamen Medikamenten und vor/nach kreislaufbelastenden Tätigkeiten\n• „Wenn etwas nicht stimmt“ (Unwohlsein)","kw":"Mobilisation|mobilis; Schock|schock; Operation|operation; Aufnahme|aufnahme; Medikamente|medikament; Fieber|fieber; Unwohlsein|unwohl"},{"id":"K006","deck":"v","q":"Was ist der Blutdruck?","a":"Kraft, die das Blut auf die Gefäßwand der Arterien und Venen ausübt.\nGemessen wird in der Einheit mmHg (Millimeter Quecksilbersäule).","kw":"Kraft; Blut; Gefäßwand|gefass; Arterien|arteri; Venen|vene; mmHg|mmhg/millimeter; Quecksilber"},{"id":"K007","deck":"v","q":"Systolisch und diastolisch – was ist was?","a":"Entsprechend der Herzaktivität:\n• systolischer Blutdruck = oberer Wert = Systole = Auswurfphase\n• diastolischer Blutdruck = unterer Wert = Diastole = Erschlaffungsphase\nBeispiel 120/80 mmHg: 120 systolisch, 80 diastolisch. Beide Werte werden in mmHg angegeben.","kw":"systolisch|systol; oberer; Auswurfphase|auswurf; diastolisch|diastol; unterer; Erschlaffungsphase|erschlaff; 120; 80"},{"id":"K008","deck":"v","q":"Aus welchen Teilen besteht ein Blutdruckmessgerät?","a":"Manschette (am Oberarm) · Aufblasballon · Ventil · Manometer (Druckanzeige) · Stethoskop (zum Abhören)","kw":"Manschette; Aufblasballon|ballon; Ventil; Manometer; Stethoskop"},{"id":"K009","deck":"v","q":"Wann wird der Blutdruck gemessen? (Indikationen)","a":"• Bei Neuaufnahmen und bei Herz-/Kreislauferkrankungen\n• Regelmäßig während des Krankenhausaufenthalts bzw. nach Versorgungsauftrag\n• Vor, während und nach Operationen\n• Vor der Mobilisation\n• Bei bekannter Hyper- oder Hypotonie\n• Bei Kreislaufkollaps = akute Hypotonie\n• Bei Gabe blutdruckbeeinflussender Medikamente\n• Bei starken Blutdruckschwankungen\n• Nach Unfällen, bei Blut-/Flüssigkeitsverlusten und bei Schock\n• „Wenn etwas nicht stimmt“","kw":"Aufnahme|aufnahme; Operation|operation; Mobilisation|mobilis; Hypertonie|hyper; Hypotonie|hypo; Kreislaufkollaps|kollaps; Medikamente|medikament; Schock|schock"},{"id":"K010","deck":"v","q":"Grundsätze bei der Blutdruckmessung","a":"• Stets unter gleichen Bedingungen messen, um verschiedene Werte beurteilen zu können: in Ruhe, immer im Liegen oder im Sitzen, immer am gleichen Arm.\n• Beim ersten Mal wird an beiden Armen gemessen.\n• Messung immer sofort dokumentieren.\n• Bei Abweichungen Arzt bzw. Pflegefachkraft informieren.","kw":"gleichen Bedingungen|gleich; Ruhe; Liegen|lieg; Sitzen|sitz; gleichen Arm|arm; beiden Armen|beiden; dokumentieren|dokument; informieren|informier"},{"id":"K011","deck":"v","q":"Warum wird beim ersten Mal an beiden Armen gemessen?","a":"• Um den Ausgangswert festzustellen.\n• Beispiel: Bei einer Verengung der A. subclavia ist eine Druckdifferenz von mehr als 20 mmHg zwischen rechtem und linkem Arm möglich.","kw":"Ausgangswert|ausgang; subclavia; Verengung|verengung; 20; Arm"},{"id":"K012","deck":"v","q":"An welchem Arm darf der Blutdruck NICHT gemessen werden?","a":"Nicht am jeweils betroffenen Arm messen:\n• bei Lymphödem (Arm geschwollen)\n• bei Parese / Plegie (Lähmung)\n• bei venösen oder arteriellen Gefäßzugängen (z. B. Viggo)\n• bei einem Dialyse-Shunt (auf keinen Fall!)\n• nach Ablatio mammae (Mastektomie)","kw":"Lymphödem|lymph; Parese|parese; Plegie|plegie/lahmung; Gefäßzugänge|zugang; Viggo|viggo/wiggo; Shunt|shunt/schunt; Ablatio mammae|ablatio; Mastektomie|mastektomie"},{"id":"K013","deck":"v","q":"Vorbereitung der auskultatorischen Blutdruckmessung","a":"1. Pflegeempfänger hält ca. 15 Minuten Ruhephase ein – sonst falsch hohe Werte.\n2. Geeignete Manschette auswählen.\n3. Blutdruckmessgerät und Stethoskop bereitlegen.\n4. Lage: sitzen (Füße auf dem Boden) oder liegen.\n5. Kleidung, die den Arm bedeckt, entfernen – sie darf nicht einschnüren.\n6. Arm auf Herzhöhe abstützen, im Sitzen Ellenbogen leicht anwinkeln.","kw":"Ruhephase|ruhe; Manschette|manschette; Stethoskop|stethoskop; Sitzen|sitz; Liegen|lieg; Kleidung|kleid; einschnüren|einschn; Herzhöhe|herz"},{"id":"K014","deck":"v","q":"Manschette richtig anlegen","a":"Luftleere Manschette am Oberarm ca. 2–3 cm oberhalb der Ellenbeuge anlegen. Die Markierung zeigt auf die Ellenbeuge (A. brachialis). Nicht zu locker und nicht zu fest: 1–2 Finger sollen gerade noch zwischen Arm und Manschette passen.","kw":"luftleer|luftleer; Oberarm|oberarm; Ellenbeuge|ellenbeug; Markierung|markier; Finger; locker; fest"},{"id":"K015","deck":"v","q":"Aufpumpen – bis wohin?","a":"Ventil schließen. Aufblasballon pumpen, bis der Puls an der A. radialis nicht mehr tastbar ist. Dann noch weitere 30 mmHg aufpumpen und dabei den Manometerzeiger beobachten. Jetzt fließt unter dem aktuellen Druck kein Blut mehr durch die A. brachialis.","kw":"Ventil; schließen|schliess; radialis; nicht mehr tastbar|tastbar; 30; Manometer; brachialis"},{"id":"K016","deck":"v","q":"Abhören und Ablassen: wie geht das?","a":"• Oliven des Stethoskops in die Ohren, Membran in die Ellenbeuge (A. brachialis) legen und mit Zeige- und Mittelfinger festhalten.\n• Ventil mit der anderen Hand langsam öffnen (3–5 mmHg pro Sekunde).\n• Erster hörbarer Ton: Manometerstand = systolischer Wert.\n• Letzter hörbarer Ton: Manometerstand = diastolischer Wert.\n• Restliche Luft zügig entweichen lassen.","kw":"Oliven|oliv; Membran|membran; Ellenbeuge|ellenbeug; langsam|langsam; erster|erste; systolisch|systol; letzter|letzte; diastolisch|diastol"},{"id":"K017","deck":"v","q":"Was sind Korotkow-Töne?","a":"Pulssynchrone Strömungsgeräusche, die beim langsamen Ablassen der Luft über dem Stethoskop zu hören sind. Der erste Ton zeigt den systolischen, der letzte Ton den diastolischen Wert.","kw":"pulssynchron|puls; Strömungsgeräusche|stromung; erster Ton|erste; systolisch|systol; letzter Ton|letzte; diastolisch|diastol"},{"id":"K018","deck":"v","q":"Nachbereitung der Blutdruckmessung","a":"1. Manschette entfernen.\n2. Pflegeempfänger über den gemessenen Wert informieren.\n3. Falls nötig, beim Ankleiden behilflich sein.\n4. Messgerät desinfizieren.\n5. Werte dokumentieren und die zuständige Pflegefachkraft informieren.","kw":"Manschette|manschette; informieren|informier; Ankleiden|ankleid; desinfizieren|desinfi; dokumentieren|dokument; Pflegefachkraft|pflegefach"},{"id":"K019","deck":"v","q":"Auskultatorisch oder oszillometrisch – was ist der Unterschied?","a":"Auskultatorisch: manuell mit Manschette und Stethoskop; du hörst die Korotkow-Töne ab.\nOszillometrisch: elektronisch; das Gerät erfasst selbst die Druckschwankungen in der Manschette.","kw":"auskultatorisch|auskult; Stethoskop|stethoskop; oszillometrisch|oszillo; elektronisch|elektron; Gerät|gerat"},{"id":"K020","deck":"w","q":"Arteria (A.)","a":"Schlagader – führt das Blut vom Herzen weg.","kw":"Schlagader|schlag; Herz; Blut"},{"id":"K021","deck":"w","q":"Vena (V.)","a":"Vene, Blutader – führt das Blut zum Herzen zurück.","kw":"Vene|vene; Blutader|blutader; Herz"},{"id":"K022","deck":"w","q":"Kapillaren (lat. capillus = Haar)","a":"Haargefäße – die kleinsten Blutgefäße zwischen Arterien und Venen.","kw":"Haargefäße|haar; klein; Arterien|arteri; Venen|vene"},{"id":"K023","deck":"w","q":"A. carotis","a":"Halsschlagader – zentraler Pulsmessort.","kw":"Hals; Schlagader|schlag"},{"id":"K024","deck":"w","q":"A. femoralis","a":"Leistenarterie – zentraler Pulsmessort.","kw":"Leiste; Arterie|arteri"},{"id":"K025","deck":"w","q":"A. temporalis","a":"Schläfenarterie – peripherer Pulsmessort.","kw":"Schläfe|schlaf; Arterie|arteri"},{"id":"K026","deck":"w","q":"A. brachialis","a":"Oberarmarterie – hier wird beim Blutdruckmessen abgehört.","kw":"Oberarm|oberarm; Arterie|arteri"},{"id":"K027","deck":"w","q":"A. radialis","a":"Speichenarterie – am Handgelenk (Daumenseite), Standardort für die manuelle Pulsmessung.","kw":"Speiche|speiche; Handgelenk|handgelenk; Daumen"},{"id":"K028","deck":"w","q":"A. ulnaris","a":"Ellenarterie – verläuft an der Elle (Kleinfingerseite des Unterarms).","kw":"Elle|elle; Arterie|arteri"},{"id":"K029","deck":"w","q":"A. poplitea","a":"Kniekehlenarterie.","kw":"Kniekehle|kniekehle"},{"id":"K030","deck":"w","q":"A. tibialis posterior","a":"Hintere Schienbeinarterie.","kw":"hintere|hinter; Schienbein|schienbein"},{"id":"K031","deck":"w","q":"A. dorsalis pedis","a":"Fußrückenarterie (dorsal = Rücken, Pes/pedis = Fuß).","kw":"Fußrücken|fussruck; Fuß|fuss; Rücken|ruck"},{"id":"K032","deck":"w","q":"A. subclavia","a":"Schlüsselbeinarterie (sub = unter, Clavicula = Schlüsselbein). Bei einer Verengung kann der Blutdruck zwischen den Armen um mehr als 20 mmHg abweichen.","kw":"Schlüsselbein|schlussel; unter; Verengung|verengung; 20"},{"id":"K033","deck":"w","q":"Hypertonie","a":"Bluthochdruck (hyper = über, zu viel; Tonus = Spannung).","kw":"Bluthochdruck|hoch; hyper|hyper; zu viel|viel"},{"id":"K034","deck":"w","q":"Hypotonie","a":"Zu niedriger Blutdruck (hypo = unter, zu wenig).","kw":"niedrig; hypo|hypo; wenig"},{"id":"K035","deck":"w","q":"Hyper- und Hypo-","a":"Hyper- = über, zu viel. Hypo- = unter, zu wenig.","kw":"über|uber; viel; unter; wenig"},{"id":"K036","deck":"w","q":"Tachykardie und Bradykardie","a":"Tachykardie = zu schneller Herzschlag (tachy = schnell).\nBradykardie = zu langsamer Herzschlag (brady = langsam).","kw":"schnell; langsam; Herzschlag|herz"},{"id":"K037","deck":"w","q":"-itis","a":"Entzündung (z. B. Bronchitis = Entzündung der Bronchien).","kw":"Entzündung|entzund"},{"id":"K038","deck":"w","q":"kardiovaskulär","a":"Herz (kardio) und Gefäße (vaskulär) betreffend – das Herz-Kreislauf-System.","kw":"Herz; Gefäße|gefass"},{"id":"K039","deck":"w","q":"Indikation","a":"Grund bzw. Anlass, eine Maßnahme durchzuführen (z. B. Blutdruckmessung nach einem Unfall).","kw":"Grund; Anlass; Maßnahme|massnahme"},{"id":"K040","deck":"w","q":"Auskultation","a":"Abhören (z. B. mit dem Stethoskop).","kw":"Abhören|abhor; Stethoskop"},{"id":"K041","deck":"w","q":"Stethoskop","a":"Abhörgerät (griech. stethos = Brust, skopein = betrachten).","kw":"Abhör|abhor; Gerät|gerat; Brust"},{"id":"K042","deck":"w","q":"Manometer","a":"Druckmessgerät – zeigt den Manschettendruck in mmHg an.","kw":"Druck; mmHg|mmhg/millimeter; Messgerät|messgerat"},{"id":"K043","deck":"w","q":"Parese","a":"Unvollständige Lähmung (Teillähmung).","kw":"unvollständig|unvollstand; Lähmung|lahmung; Teil"},{"id":"K044","deck":"w","q":"Plegie","a":"Vollständige Lähmung.","kw":"vollständig|vollstand; Lähmung|lahmung"},{"id":"K045","deck":"w","q":"Lymphödem","a":"Schwellung durch gestaute Lymphflüssigkeit (Ödem = Wassereinlagerung im Gewebe). Am betroffenen Arm nicht den Blutdruck messen.","kw":"Schwellung|schwell; Lymph; Wasser"},{"id":"K046","deck":"w","q":"Ablatio mammae (Mastektomie)","a":"Operative Entfernung der Brust. Am betroffenen Arm nicht den Blutdruck messen.","kw":"Entfernung|entfern; Brust; Operation|operat"},{"id":"K047","deck":"w","q":"Dialyse-Shunt","a":"Operativ angelegte Verbindung zwischen Arterie und Vene am Arm für die Dialyse. Dort auf keinen Fall Blutdruck messen!","kw":"Verbindung|verbind; Arterie|arteri; Vene|vene; Dialyse|dialyse; keinen Fall|kein"},{"id":"K048","deck":"w","q":"Viggo","a":"Handelsname für eine venöse Verweilkanüle (Venenzugang). Am Arm mit Gefäßzugang nicht den Blutdruck messen.","kw":"Venenzugang|venen/zugang; Kanüle|kanul; Vene|vene"},{"id":"K049","deck":"w","q":"Mobilisation","a":"Den Pflegeempfänger in Bewegung bringen, z. B. Aufstehen aus dem Bett. Vorher werden oft Puls und Blutdruck kontrolliert.","kw":"Bewegung|beweg; Aufstehen|aufsteh; Bett"},{"id":"K050","deck":"w","q":"Prophylaxe","a":"Vorbeugung (z. B. Dekubitusprophylaxe, Sturzprophylaxe).","kw":"Vorbeugung|vorbeug; Dekubitus|dekubitus; Sturz"},{"id":"K051","deck":"w","q":"Dekubitus","a":"Druckgeschwür (Wundliegen). Dazu gibt es einen Expertenstandard: Dekubitusprophylaxe.","kw":"Druck; Geschwür|geschwur; Wundliegen|wundlieg"},{"id":"K052","deck":"w","q":"kurativ","a":"Heilend – Wiederherstellung der Gesundheit ist möglich (Krankenhaus, ambulante Pflege).","kw":"heilend|heil; Gesundheit|gesundheit; Krankenhaus|krankenhaus"},{"id":"K053","deck":"w","q":"präventiv","a":"Vorbeugend, verhütend (Prävention) – Maßnahmen, damit unerwünschte Ereignisse gar nicht erst entstehen.","kw":"vorbeugend|vorbeug; verhüt|verhut; Prävention|praventi"},{"id":"K054","deck":"w","q":"rehabilitativ","a":"Wiederherstellend – Wiedereingliederung nach Krankheit (medizinisch, beruflich, sozial), z. B. in Reha-Kliniken.","kw":"Wiederherstellung|wiederherstell; Wiedereingliederung|wiedereingl; Reha"},{"id":"K055","deck":"w","q":"palliativ","a":"Lindernd – Beschwerden und Schmerzen lindern, um die Lebensqualität zu verbessern (Hospiz, Palliativstation).","kw":"lindernd|linder; Schmerz; Lebensqualität|lebensqualitat; Hospiz"},{"id":"K056","deck":"w","q":"Salutogenese","a":"lat. salus = Gesundheit, Wohlbefinden; griech. Genese = Entstehung. Rahmenkonzept zur Entstehung und Erhaltung von Gesundheit.","kw":"Gesundheit|gesundheit; Entstehung|entstehung; Erhaltung|erhalt"},{"id":"K057","deck":"w","q":"Pathogenese","a":"griech. patho = Leiden; Genese = Entstehung. Krankheitsentstehung – Modell zur Analyse und Kontrolle von Risikofaktoren.","kw":"Leiden|leid; Krankheit|krankheit; Entstehung|entstehung; Risikofaktoren|risiko"},{"id":"K058","deck":"w","q":"Resilienz","a":"Psychische Widerstandskraft – Krisen bewältigen. Resilienzfaktoren stärken, statt nur Defizite zu sehen.","kw":"Widerstandskraft|widerstand; Krise|kris"},{"id":"K059","deck":"w","q":"evidenzbasiert","a":"Auf wissenschaftlichen Belegen (Evidenz) beruhend – so sind z. B. die Expertenstandards entwickelt.","kw":"wissenschaft; Belege|beleg; Evidenz|eviden"},{"id":"K060","deck":"w","q":"intrinsisch und extrinsisch","a":"Intrinsisch = von innen heraus (Freude an der Sache). Extrinsisch = von außen (Belohnung, Lob, Noten, Geld).","kw":"innen; außen|aussen; Belohnung|belohn"},{"id":"K061","deck":"w","q":"deklaratives und nondeklaratives Gedächtnis","a":"Deklarativ = Fachwissen, das man benennen kann. Nondeklarativ = Erfahrungen, Gewohnheiten, Bewegungsabläufe. Beides ist im Langzeitgedächtnis gespeichert.","kw":"Fachwissen|fachwissen; Erfahrung|erfahrung; Gewohnheit|gewohn; Bewegungsabläufe|bewegung; Langzeit"},{"id":"K062","deck":"w","q":"Vitalzeichen","a":"Lebenszeichen, z. B. Blutdruck, Puls, Atmung, Temperatur.","kw":"Blutdruck|blutdruck; Puls; Atmung|atmung; Temperatur|temperatur"},{"id":"K063","deck":"s","q":"Wie wird Pflege definiert? (ICN)","a":"Pflege umfasst die eigenverantwortliche Versorgung und Betreuung von Menschen aller Altersgruppen, von Familien und Gemeinschaften, ob krank oder gesund, in allen Lebenssituationen – allein oder zusammen mit anderen Berufsgruppen.\nDazu gehören Förderung der Gesundheit, Verhütung von Krankheiten sowie Versorgung und Betreuung kranker, behinderter und sterbender Menschen.","kw":"eigenverantwortlich|eigenverantwort; Versorgung|versorg; Betreuung|betreu; Altersgruppen|alter; Gesundheit|gesundheit; Verhütung|verhut; sterbende|sterben"},{"id":"K064","deck":"s","q":"Welche Aufgaben übernimmt man in der Pflege?","a":"Beratung von kranken und pflegebedürftigen Menschen mit körperlichen oder psychischen Einschränkungen sowie Betreuung, Versorgung und Aktivierung zum Erhalt von Fähigkeiten und Fertigkeiten im Alltag, z. B. Grundpflege.","kw":"Beratung|beratung; Betreuung|betreu; Versorgung|versorg; Aktivierung|aktivier; Grundpflege|grundpflege"},{"id":"K065","deck":"s","q":"Wie hat sich die Pflege geschichtlich entwickelt?","a":"Über mehrere Jahrhunderte von der Pflege aus Nächstenliebe und Barmherzigkeit zu einem anerkannten Berufsbild. Vor allem im 20. Jahrhundert gab es viele berufspolitische Entwicklungen, die ersten Berufsbilder wurden begründet und die Ausbildung mehrfach reformiert. Das Pflegeberufereformgesetz (seit 2020 gültig) macht einen weiteren Schritt Richtung Profession.","kw":"Nächstenliebe|nachstenliebe; Barmherzigkeit|barmherz; Berufsbild|berufsbild; 20; Reform|reform; Profession|profession"},{"id":"K066","deck":"s","q":"Was gehört zu den Aufgaben von Pflegefachassistentinnen und -assistenten?","a":"• Unterstützung, Übernahme und Anleitung bei Körperhygiene, Mobilisation, prophylaktischen Maßnahmen, Ausscheidung und Ernährung\n• Unterstützung und Begleitung bei anfallenden Aufgaben außerhalb der Wohnung\n• Mitwirkung bei diagnostischen und therapeutischen Maßnahmen\n• Dokumentation, Protokolle und Arbeitsnachweise","kw":"Körperhygiene|hygiene; Mobilisation|mobilis; prophylaktisch|prophylakt; Ausscheidung|ausscheid; Ernährung|ernahr; Mitwirkung|mitwirk; Dokumentation|dokument"},{"id":"K067","deck":"s","q":"Wie ist die Ausbildung zur Pflegefachassistenz aufgebaut?","a":"Einjährige Ausbildung mit theoretischem und praktischem Unterricht (laut Skript 700 Stunden) sowie praktischer Ausbildung. Sie schließt mit einer staatlich anerkannten Prüfung nach Landesrecht ab. (Bitte die Zahlen im Skript noch einmal gegenprüfen.)","kw":"einjährig|einjahr; Unterricht|unterricht; praktisch|prakti; staatlich|staatlich; Prüfung|prufung"},{"id":"K068","deck":"s","q":"Was ist Laienpflege?","a":"Pflegende Tätigkeiten, die eine Person übernimmt, die keine Ausbildung im Pflegebereich hat. Oft sind es Angehörige oder Bekannte der pflegebedürftigen Person.","kw":"Ausbildung|ausbildung; Angehörige|angehor; Bekannte|bekannt; keine"},{"id":"K069","deck":"s","q":"Was beschreiben Expertenstandards?","a":"Evidenzbasierte Qualitätsinstrumente, die von Pflegeexperten erarbeitet wurden und auf dem Konsens der Berufsgruppe beruhen. Sie sollen die Qualität in der Pflege spürbar verbessern. Entwickelt vom DNQP (Deutsches Netzwerk für Qualitätsentwicklung in der Pflege; im Skript steht „Qualitätssicherung“) mit dem Deutschen Pflegerat und mit Förderung des Bundesgesundheitsministeriums.","kw":"Qualität|qualitat; evidenzbasiert|evidenz; Konsens|konsens; DNQP|dnqp/netzwerk; Pflegerat|pflegerat"},{"id":"K070","deck":"s","q":"Nenne Beispiele für Expertenstandards","a":"• Dekubitusprophylaxe in der Pflege\n• Schmerzmanagement in der Pflege\n• Sturzprophylaxe in der Pflege\n• Beziehungsgestaltung in der Pflege von Menschen mit Demenz\n• Förderung der Mundgesundheit in der Pflege","kw":"Dekubitus|dekubitus; Schmerz|schmerz; Sturz|sturz; Demenz|demenz; Mundgesundheit|mundgesund"},{"id":"K071","deck":"s","q":"Wozu sind Pflegefachassistentinnen und -assistenten verpflichtet?","a":"Sie sind verpflichtet, die wissenschaftlichen und gesetzlichen Grundlagen der pflegebedürftigen Menschen zu sehen, zu respektieren und zu beachten.","kw":"wissenschaftlich|wissenschaft; gesetzlich|gesetz; sehen; respektieren|respekt; beachten|beacht"},{"id":"K072","deck":"s","q":"Grundgesetz Artikel 1","a":"„Die Würde des Menschen ist unantastbar.“ Dieser Satz bildet die Basis für ein friedliches Zusammenleben und für ein würdevolles, personenzentriertes Pflegeverständnis.","kw":"Würde|wurde; Menschen|mensch; unantastbar|unantast"},{"id":"K073","deck":"s","q":"Wofür gibt es die Pflege-Charta?","a":"Die Pflege-Charta wurde von Vertretern aus allen Bereichen der Pflege und Selbsthilfe entwickelt, um die Rechte der Betroffenen zu stärken und eine Grundlage für eine würdevolle Pflegepraxis zu schaffen. Sie umfasst acht Artikel.","kw":"Rechte|recht; Betroffenen|betroffen; würdevoll|wurdevoll; Pflegepraxis|pflegepraxis; acht|acht/8"},{"id":"K074","deck":"s","q":"Pflege-Charta Artikel 1","a":"Selbstbestimmung und Hilfe zur Selbsthilfe – das Recht auf ein möglichst selbstbestimmtes Leben und auf Unterstützung zur Selbsthilfe.","kw":"Selbstbestimmung|selbstbestimm; Selbsthilfe|selbsthilfe; Unterstützung|unterstutz"},{"id":"K075","deck":"s","q":"Pflege-Charta Artikel 2","a":"Körperliche und seelische Unversehrtheit, Freiheit und Sicherheit – das Recht, vor Gefahren für Leib und Seele geschützt zu werden und in Freiheit und Sicherheit zu leben.","kw":"körperlich|korper; seelisch|seel; Unversehrtheit|unversehrt; Freiheit|freiheit; Sicherheit|sicherheit"},{"id":"K076","deck":"s","q":"Pflege-Charta Artikel 3","a":"Privatheit – das Recht auf Wahrung und Schutz der Privat- und Intimsphäre.","kw":"Privat|privat; Intimsphäre|intim; Schutz|schutz"},{"id":"K077","deck":"s","q":"Pflege-Charta Artikel 4","a":"Pflege, Betreuung und Behandlung – das Recht auf eine qualifizierte, auf den persönlichen Bedarf ausgerichtete Pflege und Behandlung.","kw":"qualifiziert|qualifiz; persönlich|personlich; Bedarf|bedarf; Behandlung|behandlung"},{"id":"K078","deck":"s","q":"Pflege-Charta Artikel 5","a":"Information, Beratung und Aufklärung – das Recht auf umfassende Informations-, Hilfe- und Behandlungsangebote.","kw":"Information|information; Beratung|beratung; Aufklärung|aufklar; umfassend|umfassend"},{"id":"K079","deck":"s","q":"Pflege-Charta Artikel 6","a":"Kommunikation, Wertschätzung und Teilhabe – das Recht auf Wertschätzung und Austausch mit anderen Menschen, um am gesellschaftlichen Leben teilzunehmen.","kw":"Kommunikation|kommunikation; Wertschätzung|wertschatz; Teilhabe|teilhabe; Austausch|austausch"},{"id":"K080","deck":"s","q":"Pflege-Charta Artikel 7","a":"Religion, Kultur und Weltanschauung – das Recht, entsprechend der eigenen Kultur und Weltanschauung zu leben und die Religion auszuüben.","kw":"Religion|religion; Kultur|kultur; Weltanschauung|weltanschau"},{"id":"K081","deck":"s","q":"Pflege-Charta Artikel 8","a":"Palliative Begleitung, Sterben und Tod – das Recht, in Würde zu sterben und eine entsprechende palliative Begleitung zu erhalten.","kw":"palliativ|palliativ; Begleitung|begleit; Sterben|sterb; Würde|wurde"},{"id":"K082","deck":"s","q":"Für wen gilt der ICN-Ethikkodex?","a":"Er gilt in allen Mitgliedsstaaten des ICN (International Council of Nurses) und richtet sich an Pflegefachpersonen aller Qualifikationsstufen – egal, in welchen Arbeitsfeldern oder Praxisgebieten sie tätig sind, z. B. in Pflegeheimen, Krankenhäusern und der ambulanten Pflege.","kw":"Mitgliedsstaaten|mitglied; ICN|icn; Qualifikation|qualifikation; Arbeitsfeld|arbeitsfeld; ambulant|ambulant"},{"id":"K083","deck":"s","q":"Wie viele Grundelemente hat der ICN-Ethikkodex?","a":"Vier:\n1. Pflegende und ihre Mitmenschen\n2. Pflegende und die Pflegepraxis\n3. Pflegende und ihre Profession\n4. Pflegende und ihre Kollegen (so im Skript; die neuere ICN-Fassung von 2021 nennt hier „Pflegefachpersonen und globale Gesundheit“ – bei der Lehrkraft nachfragen)","kw":"vier|vier/4; Mitmenschen|mitmensch; Pflegepraxis|pflegepraxis; Profession|profession; Kollegen|kolleg"},{"id":"K084","deck":"s","q":"ICN-Kodex Element 1: Pflegende und ihre Mitmenschen","a":"Pflegende respektieren die Würde, das Leben, die Gesundheit, die Freiheit, die Meinungen, die Sitten, Gewohnheiten und Bedürfnisse aller Menschen – unabhängig von Alter, Geschlecht, Hautfarbe, Religion, sozialem Status oder anderen Merkmalen.","kw":"Würde|wurde; Leben|leben; Gesundheit|gesundheit; Freiheit|freiheit; unabhängig|unabhang; Alter|alter; Religion|religion"},{"id":"K085","deck":"s","q":"ICN-Kodex Element 2: Pflegende und die Pflegepraxis","a":"Pflegende sind persönlich verantwortlich für ihre berufliche Tätigkeit. Sie müssen fachlich kompetent bleiben, z. B. durch Weiterbildung, und gewährleisten Sicherheit und Würde der Patienten bei der Anwendung neuer Technologien und wissenschaftlicher Erkenntnisse.","kw":"verantwortlich|verantwort; kompetent|kompetent; Weiterbildung|weiterbild; Sicherheit|sicherheit; Würde|wurde; Technologien|technolog"},{"id":"K086","deck":"s","q":"ICN-Kodex Element 3: Pflegende und ihre Profession","a":"Pflegende haben die Verantwortung, die Integrität und die Qualität der Pflege professionell zu wahren. Dazu gehören die Mitwirkung an Forschung, das Setzen von Standards und die Einhaltung der Berufsregeln.","kw":"Verantwortung|verantwort; Integrität|integrit; Qualität|qualit; Forschung|forschung; Standards|standard; Berufsregeln|berufsregeln"},{"id":"K087","deck":"s","q":"Die Maslow-Bedürfnispyramide (von unten nach oben)","a":"1. Physiologische Bedürfnisse – Atmen, Essen, Trinken, Schlaf, Wärme\n2. Sicherheitsbedürfnisse – Schutz, Stabilität, Ordnung\n3. Soziale Bedürfnisse – Zugehörigkeit, Kommunikation, Freundschaft, Liebe\n4. Individualbedürfnisse – Anerkennung, Wertschätzung, Status\n5. Selbstverwirklichung – die eigenen Fähigkeiten entfalten","kw":"physiologisch|physiolog; Sicherheit|sicherheit; sozial|sozial; Individual|individual; Anerkennung|anerkenn; Selbstverwirklichung|selbstverwirk"},{"id":"K088","deck":"s","q":"Welche vier Handlungsfelder der Pflege gibt es?","a":"• kurativ – heilend (Krankenhaus, ambulante Pflege)\n• präventiv – vorbeugend (private Räume, ambulante Versorgung)\n• rehabilitativ – Wiederherstellung (Reha-Kliniken)\n• palliativ – lindernd (Hospiz, Palliativstation)","kw":"kurativ|kurativ; präventiv|praventiv; rehabilitativ|rehabilit; palliativ|palliativ; Krankenhaus|krankenhaus; Hospiz|hospiz"},{"id":"K089","deck":"s","q":"Was bedeutet Handeln?","a":"Aufgabengemäß, zielgerichtet und verantwortungsbewusst tätig werden, situationsbedingt aktiv werden und Probleme lösen. Alltägliches Handeln wird durch Übung automatisiert; so entstehen feste, kraftsparende Gewohnheiten, die weitgehend unbewusst ablaufen und das Denken für andere Prozesse entlasten.","kw":"aufgabengemäß|aufgabengema; zielgerichtet|zielgericht; verantwortungsbewusst|verantwortungsbewusst; situationsbedingt|situation; Probleme|problem; Gewohnheit|gewohn"},{"id":"K090","deck":"s","q":"Was bedeutet Kompetenz?","a":"Die Fähigkeit und Bereitschaft des Einzelnen, Kenntnisse und Fertigkeiten sowie persönliche, soziale und methodische Fähigkeiten zu nutzen und sich durchdacht, individuell und sozialverantwortlich zu verhalten. Man spricht von Handlungskompetenz.","kw":"Fähigkeit|fahigkeit; Bereitschaft|bereitschaft; Kenntnisse|kenntnis; Fertigkeiten|fertigkeit; sozialverantwortlich|sozialverantwort; Handlungskompetenz|handlungskompetenz"},{"id":"K091","deck":"s","q":"Fachkompetenz – was gehört dazu?","a":"Fachlich-inhaltliches Lernen: berufliche Grundlagen kennen, anwenden und beurteilen. Sie umfasst theoretische Kenntnisse und praktisch anwendbares Handlungswissen.\nBeispiel: wissenschaftliche Erkenntnisse einbeziehen, Zusammenhänge verstehen, Expertenstandards und RKI-Richtlinien in der beruflichen Praxis anwenden.","kw":"Kenntnisse|kenntnis; Fertigkeiten|fertigkeit; Anwenden|anwend; Expertenstandards|expertenstandard; RKI|rki"},{"id":"K092","deck":"s","q":"Methodenkompetenz – was gehört dazu?","a":"Planmäßig und zielorientiert vorgehen, nichts dem Zufall überlassen: problemlösendes Denken, Analyse-, Transfer-, Planungs- und Entscheidungsfähigkeit, Informationsbeschaffung, Rhetorik.\nBeispiel: Pflegehandlungen zielorientiert durchführen, sich selbst organisieren, Prioritäten setzen.","kw":"planmäßig|planmass; zielorientiert|zielorient; Problem|problem; Planung|planung; Entscheidung|entscheid; Prioritäten|prioritat; organisieren|organis"},{"id":"K093","deck":"s","q":"Sozialkompetenz – was gehört dazu?","a":"Beziehungen gestalten und mit anderen Menschen situationsadäquat handeln: Teamfähigkeit, Hilfsbereitschaft, Fairness, Kooperation, Konfliktfähigkeit, Toleranz, Kritik annehmen und äußern.\nBeispiel: Pflegeprozesse als Beziehungsprozess gestalten, Biographiearbeit, Umgang mit herausforderndem Verhalten.","kw":"Team; Hilfsbereitschaft|hilfsbereit; Kooperation|kooperation; Konflikt|konflikt; Toleranz|toleranz; Biographiearbeit|biographie"},{"id":"K094","deck":"s","q":"Persönlichkeitskompetenz – was gehört dazu?","a":"Die eigene Persönlichkeit weiterentwickeln, Einstellungen und Werte reflektieren: Verantwortlichkeit, Kreativität, Motivation, Initiative, Lernbereitschaft, Ausdauer, emotionale Intelligenz, realistisches Selbstbild.\nBeispiel: das eigene Handeln kontinuierlich reflektieren, sich selbst realistisch einschätzen, konstruktive Kritik vertragen.","kw":"Verantwortung|verantwort; Kreativität|kreativ; Motivation|motivation; Initiative|initiativ; emotionale Intelligenz|emotional; Selbstbild|selbstbild; Reflexion|reflek"},{"id":"K095","deck":"l","q":"Was ist Lernen? (Definition)","a":"Lernen ist die lebenslange Aneignung von Wissen, Kenntnissen und Fertigkeiten. Es ist ein Prozess, baut auf Erfahrungen auf und führt zu Veränderungen im Verhalten und Erleben (Hobmair 2013).","kw":"lebenslang|lebenslang; Aneignung|aneignung; Wissen|wissen; Fertigkeiten|fertigkeit; Prozess|prozess; Erfahrung|erfahrung"},{"id":"K096","deck":"l","q":"Welche drei Gedächtnisstufen gibt es?","a":"• Ultrakurzzeitgedächtnis: Millisekunden, wirkt wie ein Filter\n• Kurzzeitgedächtnis: Sekunden bis wenige Minuten, höchstens 9 Stück neue Informationen (Lesen: Zwischenspeicher ca. 20 Minuten)\n• Langzeitgedächtnis: Tage bis Jahre","kw":"Ultrakurzzeit|ultrakurz; Kurzzeit|kurzzeit; Langzeit|langzeit; Filter|filter; 9|9/neun; 20|20/zwanzig"},{"id":"K097","deck":"l","q":"Ultrakurzzeitgedächtnis – wie funktioniert es?","a":"Es speichert nur Millisekunden und agiert wie ein Filter: Es lässt maximal zwei Sekunden lang alle einkommenden Sinnesreize durch und sortiert Wichtiges von Unwichtigem. Nur Wichtiges kommt ins Kurzzeitgedächtnis.","kw":"Millisekunden|millisekunde; Filter|filter; Sinnesreize|sinnes; wichtig|wichtig"},{"id":"K098","deck":"l","q":"Kurzzeitgedächtnis – wie funktioniert es?","a":"Es ist der Arbeitsspeicher: Speicherdauer Sekunden bis höchstens wenige Minuten, nur etwa 9 Informationen gleichzeitig. Ohne Wiederholung und Aufmerksamkeit geht der Inhalt schnell wieder verloren. Es dient als Zwischenstation zum Langzeitgedächtnis.","kw":"Arbeitsspeicher|arbeitsspeicher; Sekunden|sekunde; Minuten|minute; 9|9/neun; Wiederholung|wiederhol; Aufmerksamkeit|aufmerksam"},{"id":"K099","deck":"l","q":"Langzeitgedächtnis – was wird dort gespeichert?","a":"Speicherdauer: Tage bis Jahre. Gespeichert werden deklaratives Wissen (Fachwissen) und nondeklaratives Wissen (Erfahrungen, Gewohnheiten, Bewegungsabläufe).","kw":"Tage; Jahre; deklarativ|deklarativ; Fachwissen|fachwissen; Erfahrung|erfahrung; Gewohnheiten|gewohn; Bewegungsabläufe|bewegung"},{"id":"K100","deck":"l","q":"Was passiert im Gehirn, wenn du etwas Neues lernst?","a":"Nervenzellen empfangen und senden Informationen über Synapsen (Kontaktstellen). Wenn du etwas wiederholt tust, werden die Nervenbahnen dicker und es bilden sich neue Verbindungen. Wie eine Karte, die erst unscharf ist und mit jeder Wiederholung schärfer und detailreicher wird. Darum ist Wiederholung so wichtig.","kw":"Nervenzellen|nerven; Synapsen|synaps; Kontaktstellen|kontakt; Wiederholung|wiederhol; dicker|dick; Verbindungen|verbind"},{"id":"K101","deck":"l","q":"Was bedeutet lebenslanges Lernen?","a":"Lernen während der gesamten Lebensphase, privat und beruflich (Fort- und Weiterbildung im Beruf). Mit Globalisierung und technologischem Fortschritt muss jeder Erwachsene neue Fähigkeiten aneignen. Eine Lernmentalität zu entwickeln wird immer wichtiger.","kw":"gesamte|gesamt; Lebensphase|lebensphase; Fort|fort; Weiterbildung|weiterbild; Globalisierung|globalis; Lernmentalität|lernmental"},{"id":"K102","deck":"l","q":"Wie lernt man als Kind, als Schulkind und als Erwachsener?","a":"• Kind: „Ich lerne, weil es mir Spaß macht.“ Neugierig, frei, aus Interesse.\n• Schulkind: „Ich lerne, weil ich das muss.“ Noten, Lehrpläne, Fremdbestimmung.\n• Erwachsener: „Ich lerne, weil ich es lernen will.“ Freiwillig, selbstbestimmt, mit Relevanz und Praxisbezug.","kw":"Kind; Spaß|spass; Schulkind|schul; muss; Erwachsene|erwachsen; will; freiwillig|freiwillig"},{"id":"K103","deck":"l","q":"Was zeichnet das Lernen von Erwachsenen aus?","a":"Erwachsene lernen freiwillig, gemeinschaftlich und selbstbestimmt, bringen Vorerfahrungen mit und werden durch Relevanz und Praxisbezug motiviert. Sie handeln problemorientiert und brauchen Freiraum, damit individuelle Lernpräferenzen berücksichtigt werden.","kw":"freiwillig|freiwillig; gemeinschaftlich|gemeinschaft; selbstbestimmt|selbstbestimm; Praxisbezug|praxisbezug; Relevanz|relevanz; problemorientiert|problemorient; Freiraum|freiraum"},{"id":"K104","deck":"l","q":"Was sind formales, non-formales und informelles Lernen?","a":"Formales Lernen: organisiert, strukturiert, rein auf das Lernen fokussiert und führt zu einer Qualifikation oder einem Zertifikat.\nInformelles Lernen: findet im (Berufs-)Alltag statt, unbewusst und nicht zertifizierbar.\nNon-formales Lernen liegt dazwischen.","kw":"formal|formal; organisiert|organis; strukturiert|struktur; Zertifikat|zertifikat; informell|informell; Alltag|alltag; unbewusst|unbewusst"},{"id":"K105","deck":"l","q":"Die drei Phasen der Prüfungsvorbereitung","a":"1. Vorbereitungsphase: alle Materialien sammeln, Wissensstand analysieren, Zeitplan erstellen.\n2. Informationsaufbauphase: Lernstoff nach Wichtigkeit ordnen und mit Lerntechniken wie Mindmapping erstmals durcharbeiten.\n3. Aneignungsphase: wiederholen, nachlesen, vertiefen und festigen, Probeprüfungen in der Lerngruppe.","kw":"Vorbereitung|vorbereit; Informationsaufbau|informationsaufbau; Aneignung|aneignung; Mindmap|mindmap; wiederholen|wiederhol; Zeitplan|zeitplan; Lerngruppe|lerngruppe"},{"id":"K106","deck":"l","q":"Welche Tipps helfen, sich zum Lernen zu motivieren?","a":"• Rituale entwickeln (z. B. eine Tasse Tee vor dem Start)\n• Lernpartner suchen\n• Positive Einstellung entwickeln\n• Lernplatz wechseln\n• Sich nach Lernphasen belohnen\n• Visualisieren: sich erinnern, warum man das Fach gewählt hat\n• Angenehme Lernumgebung ohne Ablenkung","kw":"Rituale|ritual; Lernpartner|lernpartner; positive Einstellung|positiv; Lernplatz|lernplatz/ort; belohnen|belohn; Visualisieren|visualis; Lernumgebung|lernumgebung"},{"id":"K107","deck":"l","q":"Wie sieht eine gute Lernumgebung aus?","a":"Ablenkungsfrei: aufgeräumter Arbeitsplatz, ausreichend Platz, Helligkeit und Ruhe, ein gemütlicher Stuhl, alle Lernmaterialien bereit. Pausen einplanen und aktiv gestalten. Unterricht aktiv als Lernchance nutzen.","kw":"ablenkungsfrei|ablenk; aufgeräumt|aufgeraum; Licht|licht/hell; Ruhe|ruhe; Pausen|pause; Lernmaterial|lernmaterial"},{"id":"K108","deck":"l","q":"Welche zwei Hauptarten der Motivation gibt es?","a":"Intrinsische Motivation (kommt von innen, z. B. Freude an einer Tätigkeit) und extrinsische Motivation (kommt von außen, z. B. Belohnungen oder Druck). Beide wirken unterschiedlich auf Verhalten und Leistung.","kw":"intrinsisch|intrinsi; extrinsisch|extrinsi; innen; außen|aussen; Belohnung|belohn"},{"id":"K109","deck":"l","q":"Intrinsische Motivation – Definition, Merkmal, Beispiel","a":"Definition: Der Antrieb, eine Tätigkeit aus eigenem Interesse, für den Spaß an der Sache oder aus innerer Überzeugung auszuführen.\nMerkmal: kommt von innen, ist schwerer zu stimulieren, hat aber eine länger anhaltende Wirkung und führt oft zu höherer Kreativität und Ausdauer.\nBeispiel: ein Hobby, das man aus reiner Freude ausübt.","kw":"Antrieb|antrieb; Interesse|interesse; Spaß|spass; Überzeugung|uberzeug; innen; Hobby|hobby; Ausdauer|ausdauer"},{"id":"K110","deck":"l","q":"Extrinsische Motivation – Definition, Merkmal, Beispiel","a":"Definition: Der Antrieb, eine Handlung auszuführen, um äußere Anreize zu erhalten oder negative Konsequenzen zu vermeiden.\nMerkmal: kommt von externen Quellen; die Belohnung ist ein direkter „Booster“, wirkt aber begrenzter und kurzfristiger.\nBeispiel: arbeiten für eine Gehaltserhöhung, Lob oder Anerkennung.","kw":"Anreize|anreiz; Konsequenzen|konsequenz; extern|extern; Belohnung|belohn; kurzfristig|kurzfrist; Gehaltserhöhung|gehalt; Lob|lob"},{"id":"K111","deck":"l","q":"Was fördert die intrinsische Motivation beim Lernen?","a":"Positive Einstellung, Neugier und Offenheit gegenüber dem Lernthema; Lernziele formulieren und zeitlich festlegen (Planung); Selbstvertrauen zur eigenen Leistung stärken; Unterstützungsangebote nutzen. Dazu gehören Autonomie, Kompetenzerleben, Sinnhaftigkeit und soziale Eingebundenheit.","kw":"Neugier|neugier; Offenheit|offen; Lernziele|lernziel; Selbstvertrauen|selbstvertrau; Unterstützung|unterstutz; Autonomie|autonomie"},{"id":"K112","deck":"l","q":"Was fördert die extrinsische Motivation beim Lernen?","a":"Äußere Anreize und Einflüsse: Lob und Anerkennung, gute Noten, finanzielle Anreize wie Bezahlung oder Gehaltserhöhung, eine angenehme Lernumgebung, zusätzliche Verantwortung. Sie wirken oft nur kurzfristig und sollen die intrinsische Motivation nicht unterdrücken. Lernerfolge feiern und belohnen.","kw":"Lob|lob; Anerkennung|anerkenn; Noten|note; Gehaltserhöhung|gehalt; Lernumgebung|lernumgebung; kurzfristig|kurzfrist; belohnen|belohn"},{"id":"K113","deck":"l","q":"Welche vier Lerntypen gibt es?","a":"• Visueller Typ: lernt durch Ansehen (Videos, Grafiken, Mindmaps)\n• Auditiver Typ: lernt durch lautes Vorlesen und Anhören\n• Kommunikativer Typ: lernt durch Gespräche, in Lerngruppen\n• Motorischer Typ: lernt durch Ausprobieren und Anwenden („Learning by doing“)","kw":"visuell|visuell; auditiv|auditiv; kommunikativ|kommunikativ; motorisch|motorisch; Ansehen|ansehen; Anhören|anhor; Gespräche|gesprach; Ausprobieren|ausprobier"},{"id":"K114","deck":"l","q":"Lerntipps für den visuellen Typ","a":"Möglichst viel mitschreiben, Skizzen, Mind-Maps und Diagramme malen, Stoff in Bilder fassen, Karteikarten nutzen, Bilder und Internetbilder zum Thema suchen und Zusammenhänge verbildlichen (z. B. Eselsbrücken mit Bildern).","kw":"mitschreiben|mitschreib; Skizzen|skizz; Mindmap|mind; Diagramme|diagramm; Karteikarten|karteikart; Bilder|bild"},{"id":"K115","deck":"l","q":"Lerntipps für den auditiven Typ","a":"Texte laut vorlesen, Lernstoff aufnehmen und anhören, Lern-CDs, Hörbücher und Podcasts nutzen, Selbstgespräche führen, jemandem etwas erklären. Ruhige Umgebung, damit Geräusche nicht ablenken.","kw":"laut; vorlesen|vorles; aufnehmen|aufnehm; Podcast|podcast; Hörbücher|horbuch; erklären|erklar"},{"id":"K116","deck":"l","q":"Lerntipps für den kommunikativen Typ","a":"Mit Freunden oder Lernpartnern lernen, den Stoff besprechen und diskutieren, Rollenspiele machen, Quizrunden spielen, dem Lernpartner das Thema erklären.","kw":"Lernpartner|lernpartner/freunde; besprechen|besprech; diskutieren|diskut; Rollenspiele|rollenspiel; Quiz|quiz; erklären|erklar"},{"id":"K117","deck":"l","q":"Lerntipps für den motorischen Typ","a":"Mit Händen lernen: Modelle basteln, Lernmaterial anfassen, Rollenspiele spielen, beim Lernen im Zimmer auf und ab laufen, Gesten und Mimik einsetzen, einen Ball oder Stift in der Hand haben.","kw":"Modelle|modell; basteln|bastel; Rollenspiele|rollenspiel; laufen|lauf; Gesten|geste; Ball|ball"},{"id":"K118","deck":"l","q":"Weiterbildung oder Fortbildung – was ist der Unterschied?","a":"Weiterbildung: man eignet sich neue Fähigkeiten, Kenntnisse und Qualifikationen an, nach dem Berufsabschluss, mittlere bis längere Dauer, oft mit Aufstieg verbunden (z. B. Praxisanleiter, Fachkrankenpflege).\nFortbildung: erweitert oder ergänzt die Qualifikationen im aktuellen Beruf, kürzere Dauer, Aktualisierung von Wissen (z. B. Kommunikation, EDV, Pflegedokumentation).","kw":"Weiterbildung|weiterbildung; neue Qualifikation|neue; Aufstieg|aufstieg; Praxisanleiter|praxisanleit; Fortbildung|fortbildung; Aktualisierung|aktualis; kurz"},{"id":"K119","deck":"l","q":"Welche Phasen hat eine Gruppenarbeit?","a":"1. Rollenverteilung: wer moderiert, protokolliert, ist Zeitwächter, präsentiert?\n2. Vorbereitung: Anforderung und Arbeitsauftrag klären, Mittel und Zeitplanung, Aufgabenverteilung.\n3. Durchführung: recherchieren, Informationen clustern und überprüfen, Bearbeitung.\n4. Präsentation: Ergebnisse zusammenfassen.\n5. Feedback und Reflexion.","kw":"Rollenverteilung|rollen; moderiert|moderier; protokolliert|protokoll; Zeitwächter|zeitwacht; Vorbereitung|vorbereit; Durchführung|durchfuhr; Präsentation|prasentation; Feedback|feedback/ruckmeldung"},{"id":"K120","deck":"l","q":"Wie präsentiere ich richtig?","a":"Blickkontakt halten, trotz Lampenfieber das Publikum im Blick behalten, eine gute Position wählen, Gestik und Mimik einsetzen, gut vorbereitet sein, Ablenkungen vermeiden, selbstbewusst und frei sprechen (Füllwörter wie „ähm“ vermeiden), das Publikum einbeziehen und mit eigenen Erlebnissen auch emotional ansprechen.","kw":"Blickkontakt|blick; Lampenfieber|lampenfieber; Gestik|gestik; Mimik|mimik; vorbereitet|vorbereit; Füllwörter|fullwort; Publikum|publikum"},{"id":"K121","deck":"l","q":"Klassische Fehler bei Präsentationen","a":"Zuhörer nicht auf ihrem Wissensstand abholen, Zusammenhänge nicht erklären, monotone Stimmlage, Nachfragen nicht dulden, permanentes Ablesen, dem Publikum den Rücken zudrehen, kein Methodenwechsel, autoritäres Auftreten, konzeptloses Vorgehen, Vielrednern das Feld überlassen.","kw":"Wissensstand|wissensstand; monoton|monoton; Nachfragen|nachfrag; Ablesen|ablesen; Rücken|rucken; Methodenwechsel|methodenwechsel; autoritär|autoritar"},{"id":"K122","deck":"v","q":"Nenne die 3 Beobachtungskriterien des Pulses","a":"1. Pulsfrequenz – Anzahl der Pulsschläge pro Minute\n2. Pulsrhythmus – zeitliche Abfolge der Pulsschläge\n3. Pulsqualität – Art des Pulsschlags, der erfühlt wird (z. B. weich, hart)","kw":"Pulsfrequenz|frequenz; Anzahl|anzahl; Minute|minute; Pulsrhythmus|rhythmus; Abfolge|abfolge; Pulsqualität|qualitat; weich; hart"},{"id":"K123","deck":"v","q":"Pulsfrequenz: Normwerte nach Alter","a":"Laut Folie (Zuordnung im Foto leicht unsicher, bitte im Original prüfen):\n• Neugeborene: 140/Min.\n• Kleinkinder: 120/Min.\n• Kinder: 95/Min.\n• Jugendliche: 90/Min.\n• Erwachsene: 70/Min.\n• Ältere Menschen: 80/Min.","kw":"Neugeborene|neugeboren; 140; Kleinkinder|kleinkind; 120; Kinder|kinder; 95; Jugendliche|jugendlich; 90; Erwachsene|erwachsen; 70; Ältere|altere; 80"},{"id":"K124","deck":"v","q":"Pulsfrequenz und Herzfrequenz – was ist das Pulsdefizit?","a":"Die Pulsfrequenz stimmt normalerweise mit der Herzfrequenz überein. Ausnahme: das Pulsdefizit. Dabei zieht sich das Herz zwar zusammen, aber nicht jeder Herzschlag kommt als Puls an.","kw":"Herzfrequenz|herzfrequenz; überein|uberein; Pulsdefizit|defizit; Herz"},{"id":"K125","deck":"v","q":"Bradykardie – Definition und Ursachen","a":"Verminderte Herzfrequenz: beim Erwachsenen unter 60 Schläge pro Minute.\nPhysiologisch bei: Schlaf/Ruhe, Hungerzustand, gut trainiertem Zustand.\nPathologisch bei: erhöhtem Hirndruck, Reizbildungsstörung, Reizleitungsstörung, Hyperkaliämie, Schilddrüsenunterfunktion, Medikamenten (z. B. Betablocker), Reizung des Nervus vagus.","kw":"60; Schlaf|schlaf; Ruhe; Hunger|hunger; trainiert|trainiert; Hirndruck|hirndruck; Reizbildung|reizbildung; Reizleitung|reizleitung; Hyperkaliämie|hyperkali; Schilddrüse|schilddruse; Betablocker|blocker; Vagus|vagus"},{"id":"K126","deck":"v","q":"Tachykardie – Definition und Ursachen","a":"Gesteigerte Herz- bzw. Pulsfrequenz: beim Erwachsenen über 100 Schläge pro Minute.\nPhysiologisch bei: erhöhtem Sauerstoffbedarf (Anstrengung), Anpassung an verringerte Sauerstoffsättigung (Hochgebirgsluft), seelischer Erregung.\nPathologisch bei: krankhaft erhöhtem Stoffwechsel, verringertem Sauerstoffangebot an die Zellen (z. B. Blutverlust, Herzinsuffizienz), Störung des Herzreizleitungssystems, Hypokaliämie, Schmerzen, Medikamenten.","kw":"100; Anstrengung|anstreng; Sauerstoff|sauerstoff/o2; Hochgebirge|hochgebirg; Erregung|erregung; Stoffwechsel|stoffwechsel; Blutverlust|blutverlust; Herzinsuffizienz|insuffizienz; Hypokaliämie|hypokali; Schmerzen|schmerz; Medikamente|medikament"},{"id":"K127","deck":"v","q":"Wie verändert Fieber den Puls?","a":"Bei Fieber erhöht sich der Puls: Pro 1 °C Anstieg der Körpertemperatur steigt die Pulsfrequenz um 8 bis 12 Schläge pro Minute.\nBeispiel: 37 °C auf 39 °C = 16 bis 24 Schläge pro Minute mehr.","kw":"Fieber|fieber; Grad|grad/1; 8; 12; Schläge|schlag; 16; 24"},{"id":"K128","deck":"v","q":"Pulsrhythmus – Definition und Sinusrhythmus","a":"Pulsrhythmus = zeitliche Abfolge der Pulswellen (Herzschläge).\nSinusrhythmus (physiologisch): Bei Gesunden liegen zwischen den Pulswellen etwa gleiche Zeiträume (rhythmischer Puls). Bei Kindern und Jugendlichen ist atemabhängige Schwankung normal: beim Einatmen steigt die Frequenz, beim Ausatmen sinkt sie (respiratorische Arrhythmie).","kw":"zeitliche|zeit; Abfolge|abfolge; Sinusrhythmus|sinus; gleiche|gleich; Einatmung|einatm; Ausatmung|ausatm; respiratorisch|respirator"},{"id":"K129","deck":"v","q":"Was sind Extrasystolen?","a":"Extrasystolen (kurz ES) sind Herzschläge, die außerhalb des regulären Grundrhythmus auftreten. Vereinzelte ES haben in der Regel keinen Krankheitswert. Mehrere hintereinander haben Behandlungsbedarf.","kw":"Extrasystole|extrasystol; außerhalb|ausserhalb; Grundrhythmus|grundrhythmus; vereinzelt|vereinzelt; hintereinander|hintereinander; Behandlung|behandlung"},{"id":"K130","deck":"v","q":"Was ist eine Arrhythmie?","a":"Unregelmäßiger Pulsrhythmus: Herzrhythmusstörung mit unregelmäßigen Zeitabständen zwischen den Herzmuskelkontraktionen.\n• mit zu schneller Herzfrequenz = Tachyarrhythmie\n• mit zu langsamer Herzfrequenz = Bradyarrhythmie\nUrsachen: Herzerkrankungen, Elektrolytverschiebungen, Hormonstörungen (speziell der Schilddrüse).","kw":"unregelmäßig|unregelmass; Tachyarrhythmie|tachyarrhythm; Bradyarrhythmie|bradyarrhythm; Herzerkrankung|herzerkrank; Elektrolyt|elektrolyt; Schilddrüse|schilddruse"},{"id":"K131","deck":"v","q":"Pulsqualität: Härte und Füllung","a":"Spannung/Härte: grobe Beobachtung des systolischen Drucks. Hart = hoher Blutdruck, weich = niedriger Blutdruck.\nFüllung/Größe hängt ab von: der Blutmenge im Gefäß, der Kontraktionskraft des Herzens und der Elastizität der Gefäße.","kw":"hart; hoher|hoch; weich; niedrig; Blutmenge|blutmenge; Kontraktionskraft|kontraktion; Elastizität|elastizit"},{"id":"K132","deck":"v","q":"Großer, kleiner und fadenförmiger Puls","a":"• Großer Puls: stark und hart, z. B. bei Hypertonie oder Arteriosklerose.\n• Kleiner Puls: schlecht gefüllt, z. B. bei Hypotonie, Blutverlust, Herzinsuffizienz oder Fieber.\n• Fadenförmiger Puls: klein, schnell und schlecht messbar, z. B. beim Schock.","kw":"groß|gross; Hypertonie|hyper; klein; schlecht gefüllt|gefullt; Hypotonie|hypo; fadenförmig|faden; Schock|schock"},{"id":"K133","deck":"s","q":"Der 6-schrittige Pflegeprozess","a":"1. Informationen sammeln\n2. Probleme und Ressourcen erkennen\n3. Ziele festlegen\n4. Maßnahmen planen\n5. Maßnahmen durchführen\n6. Evaluation (Beurteilung)\nWichtig: Dein Arbeitsblatt dazu enthält absichtlich Fehler. Diese Reihenfolge ist die gängige Fachlehre. Bitte mit der Lehrkraft abgleichen.","kw":"Informationen|information; Probleme|problem; Ressourcen|ressource; Ziele|ziel; planen|plan; durchführen|durchfuhr; Evaluation|evaluation/beurteil"},{"id":"K134","deck":"s","q":"Der 4-schrittige Pflegeprozess","a":"1. Informationssammlung (Pflegeanamnese)\n2. Pflegeprobleme und Ressourcen erkennen\n3. Pflegeziele und Maßnahmen planen\n4. Durchführung und Evaluation\nWichtig: Reihenfolge aus den Überschriften deines Arbeitsblatts rekonstruiert (der Text dort ist absichtlich durcheinander). Bitte mit der Lehrkraft abgleichen.","kw":"Informationssammlung|informationssammlung/anamnese; Probleme|problem; Ressourcen|ressource; Ziele|ziel; Maßnahmen|massnahme; Durchführung|durchfuhr; Evaluation|evaluation"},{"id":"K135","deck":"s","q":"Was bedeutet evidenzbasierte Pflege (EBN)?","a":"Evidence-based Nursing: evidenzbasierte Verfahren zur objektiven Beurteilung pflegerischer Maßnahmen. Ziel: Pflegebedürftigen die beste und wirksamste Pflege zukommen zu lassen. Die Methoden sind denen der Medizin angelehnt.","kw":"Evidenz|eviden; Beurteilung|beurteil; objektiv|objektiv; beste|beste; wirksam|wirksam; Medizin|medizin"},{"id":"K136","deck":"s","q":"Die 6 Schritte der evidenzbasierten Pflege","a":"1. Auftragsklärung\n2. Fragestellung\n3. Literaturrecherche\n4. Kritische Beurteilung\n5. Implementierung und Adaptation\n6. Evaluation","kw":"Auftragsklärung|auftragsklar; Fragestellung|fragestellung; Literaturrecherche|literatur; Kritische Beurteilung|kritisch; Implementierung|implementier; Adaptation|adaptation; Evaluation|evaluation"},{"id":"K137","deck":"s","q":"Gewerkschaft und Kammer – was ist der Unterschied?","a":"Gewerkschaft: freiwillige demokratische Vereinigung von Arbeitnehmern, Gegenspieler der Arbeitgeberverbände, wahrt die Interessen der Arbeitnehmer.\nKammer: auf Landesebene eingerichtete Institution mit vom Staat übertragenen Rechten. Sie klärt berufsinterne Fragen und regelt fachliche und berufliche Belange.","kw":"Gewerkschaft|gewerkschaft; freiwillig|freiwillig; Arbeitnehmer|arbeitnehmer; Arbeitgeber|arbeitgeber; Kammer|kammer; Landesebene|landesebene; Staat|staat"},{"id":"K138","deck":"l","q":"Wie kommen Informationen ins Langzeitgedächtnis? (limbisches System)","a":"Das limbische System in der Mitte des Kopfes ist der strenge Wächter: Es prüft jede Neuigkeit (wichtig? gut oder schlecht? witzig?). Vieles wirft es weg. Besonders das, was starke Gefühle auslöst, lässt es durch. Durch Wiederholung werden die Nervenbahnen dicker und es bilden sich neue Synapsen.","kw":"limbisch|limbisch; Wächter|wachter; prüft|pruft; wichtig|wichtig; Gefühle|gefuhl; Wiederholung|wiederhol; Synapsen|synaps"},{"id":"K139","deck":"l","q":"Gedächtnis-Bild: Bibliothek und Eingangshalle","a":"Das Langzeitgedächtnis ist wie eine Bibliothek. Das Arbeitsgedächtnis (Kurzzeitgedächtnis) ist die Eingangshalle: ein Zwischenspeicher für Informationen, die man im Moment, aber nicht auf Dauer braucht. Dort verarbeitet man Sinneswahrnehmungen das erste Mal bewusst.","kw":"Bibliothek|bibliothek; Langzeit|langzeit; Eingangshalle|eingangshalle; Arbeitsgedächtnis|arbeitsgedachtnis/arbeits; Zwischenspeicher|zwischenspeicher"},{"id":"K140","deck":"l","q":"Wie organisiere ich mich beim Lernen?","a":"• Ordnerstruktur anlegen, geteilt nach CE (Lerneinheit)\n• Unterkategorien mit farbigen Registerkarten\n• Ordnerrückenschilder zum Beschriften, Locher, Heftmaschine, Trennblätter\n• Prüfungen früh planen: kurzfristiges Lernen kostet viel Energie und führt selten zum Erfolg\n• Pufferzeiten, Freizeit und Ausgleich (z. B. Bewegung) einplanen","kw":"Ordner|ordner; CE|ce; Registerkarten|register; Rückenschilder|ruckenschild; planen|plan; Pufferzeit|puffer; Ausgleich|ausgleich; Bewegung|bewegung"},{"id":"K141","deck":"l","q":"Lerntypen: was ist wissenschaftlich gesichert?","a":"Im Skript werden vier Lerntypen genannt (visuell, auditiv, kommunikativ, motorisch). Für die Prüfung gibst du das so wieder. Wissenschaftlich ist die Passung „Lerntyp = beste Methode“ aber nicht belegt (Pashler u. a. 2008). Praktisch heißt das: Nutze mehrere Kanäle gleichzeitig – lesen, laut sprechen, aufschreiben.","kw":"vier|vier/4; visuell|visuell; auditiv|auditiv; kommunikativ|kommunikativ; motorisch|motorisch; nicht belegt|beleg; mehrere Kanäle|kanal; sprechen|sprech; aufschreiben|aufschreib"},{"id":"K142","deck":"k","q":"Was ist Kommunikation?","a":"Austausch von Informationen zwischen Sender und Empfänger. Der Sender verschlüsselt eine Nachricht, der Empfänger entschlüsselt sie und gibt eine Rückmeldung. Das geschieht verbal, nonverbal und paraverbal.","kw":"Austausch|austausch; Informationen|information; Sender|sender; Empfänger|empfanger; Nachricht|nachricht; Rückmeldung|ruckmeld; verbal|verbal"},{"id":"K143","deck":"k","q":"Verbal, nonverbal, paraverbal – was ist der Unterschied?","a":"• Verbal: was gesagt wird, also die Worte.\n• Paraverbal: wie es gesagt wird – Lautstärke, Tempo, Tonfall, Pausen.\n• Nonverbal: alles ohne Worte – Mimik, Gestik, Körperhaltung, Blickkontakt, Nähe und Distanz, Berührung.","kw":"verbal|verbal; Worte|wort; paraverbal|paraverbal; Lautstärke|lautstarke; Tempo|tempo; Tonfall|tonfall; nonverbal|nonverbal; Mimik|mimik; Gestik|gestik; Körperhaltung|korperhaltung"},{"id":"K144","deck":"k","q":"Das Vier-Seiten-Modell von Schulz von Thun","a":"Jede Nachricht hat vier Seiten:\n1. Sachinhalt – worüber ich informiere\n2. Selbstkundgabe (Selbstoffenbarung) – was ich von mir zeigen\n3. Beziehung – was ich von dir halte und wie wir zueinander stehen\n4. Appell – was ich bei dir erreichen möchte\nMerkhilfe: S-S-B-A.","kw":"Sachinhalt|sach; Selbstkundgabe|selbst; Beziehung|beziehung; Appell|appell; vier|vier/4"},{"id":"K145","deck":"k","q":"Vier-Seiten-Modell: Beispiel „Die Klingel geht schon wieder!“","a":"• Sachinhalt: Die Klingel läutet.\n• Selbstkundgabe: Ich bin gestresst.\n• Beziehung: Du solltest dich besser kümmern.\n• Appell: Geh bitte hin.\nDer Empfänger hört mit vier Ohren und versteht oft etwas anderes, als der Sender meint.","kw":"Sachinhalt|sach; Klingel|klingel; Selbstkundgabe|selbst; gestresst|stress; Beziehung|beziehung; Appell|appell; vier Ohren|ohren"},{"id":"K146","deck":"k","q":"Die fünf Axiome von Watzlawick","a":"1. Man kann nicht nicht kommunizieren.\n2. Jede Kommunikation hat einen Inhalts- und einen Beziehungsaspekt.\n3. Kommunikation wird durch Interpunktion gegliedert (Ursache und Wirkung werden unterschiedlich gesehen).\n4. Es gibt digitale (verbale) und analoge (nonverbale) Kommunikation.\n5. Kommunikation ist symmetrisch oder komplementär.","kw":"nicht nicht|nicht; Inhalt|inhalt; Beziehung|beziehung; Interpunktion|interpunktion; digital|digital; analog|analog; symmetrisch|symmetr; komplementär|komplement"},{"id":"K147","deck":"k","q":"Was bedeutet „Man kann nicht nicht kommunizieren“?","a":"Auch Schweigen, Wegschauen oder eine abweisende Körperhaltung sind Kommunikation. In der Pflege sendet jedes Verhalten eine Botschaft, auch wenn ich nichts sage.","kw":"Schweigen|schweig; Verhalten|verhalt; Körperhaltung|korperhaltung; Botschaft|botschaft; Pflege|pflege"},{"id":"K148","deck":"k","q":"Die Grundhaltungen nach Carl Rogers","a":"Klientenzentrierte (personenzentrierte) Gesprächsführung mit drei Grundhaltungen:\n1. Empathie – einfühlendes Verstehen\n2. Wertschätzung – bedingungslose Akzeptanz\n3. Echtheit (Kongruenz) – ehrlich und stimmig sein\nMerkhilfe: E-W-E.","kw":"Rogers|rogers; Empathie|empath; einfühlend|einfuhl; Wertschätzung|wertschatz; Akzeptanz|akzept; Echtheit|echt; Kongruenz|kongruenz; drei|drei/3"},{"id":"K149","deck":"k","q":"Was ist aktives Zuhören?","a":"Dem Gegenüber ungeteilte Aufmerksamkeit schenken: Blickkontakt halten, nicht unterbrechen, mit eigenen Worten wiederholen (Paraphrasieren), Gefühle ansprechen („Das macht Ihnen Sorgen?“) und gezielt nachfragen.","kw":"Aufmerksamkeit|aufmerksam; Blickkontakt|blick; unterbrechen|unterbrech; Paraphrasieren|paraphras/wiederhol; Gefühle|gefuhl; nachfragen|nachfrag"},{"id":"K150","deck":"k","q":"Gewaltfreie Kommunikation nach Rosenberg: die 4 Schritte","a":"1. Beobachtung – beschreiben, ohne zu bewerten\n2. Gefühl – was ich dabei fühle\n3. Bedürfnis – was mir wichtig ist\n4. Bitte – eine konkrete Bitte formulieren\nMerkhilfe: B-G-B-B.","kw":"Beobachtung|beobacht; Gefühl|gefuhl; Bedürfnis|bedurfnis; Bitte|bitte; bewerten|bewert; Rosenberg|rosenberg"},{"id":"K151","deck":"k","q":"Welche ethischen Prinzipien gibt es in der Pflege?","a":"Nach Beauchamp und Childress vier Prinzipien:\n1. Autonomie (Selbstbestimmung)\n2. Nichtschaden\n3. Fürsorge (Wohltun)\n4. Gerechtigkeit","kw":"Autonomie|autonom; Selbstbestimmung|selbstbestimm; Nichtschaden|nichtschad/schaden; Fürsorge|fursorge; Wohltun|wohltun; Gerechtigkeit|gerecht; vier|vier/4"},{"id":"K152","deck":"k","q":"Was beeinflusst die Kommunikation in der Pflege?","a":"Störungen und Einflussfaktoren: Zeitdruck und Lärm, Sprach- und Kulturunterschiede, Hör- oder Sehbehinderung, Schmerzen, Angst und Stimmung, Demenz, fehlendes Vertrauen, Hierarchie.","kw":"Zeitdruck|zeit; Lärm|larm; Sprache|sprach; Kultur|kultur; Hörbehinderung|hor; Schmerzen|schmerz; Angst|angst; Demenz|demenz; Vertrauen|vertrau"},{"id":"K153","deck":"k","q":"Was ist Stress? Eustress und Distress","a":"Stress ist die körperliche und psychische Reaktion auf eine Belastung (Stressor). Eustress ist positiver Stress, der motiviert und leistungsfähig macht. Distress ist negativer Stress, der überfordert und auf Dauer krank machen kann.","kw":"Reaktion|reaktion; Belastung|belast; Stressor|stressor; Eustress|eustress; positiv|positiv; Distress|distress; negativ|negativ; überfordert|uberford"},{"id":"K154","deck":"k","q":"Was ist Burnout?","a":"Ein Zustand tiefer Erschöpfung durch lang anhaltende berufliche Überlastung. Nach Maslach: emotionale Erschöpfung, Distanzierung (Depersonalisation) und das Gefühl verminderter Leistungsfähigkeit. Phasenmodelle dazu sind Lehrbuchmodelle und wissenschaftlich schwach gestützt.","kw":"Erschöpfung|erschopf; Überlastung|uberlast; Maslach|maslach; Distanz|distanz; Depersonalisation|depersonal; Leistung|leistung"},{"id":"K155","deck":"k","q":"Was hilft gegen Überforderung und Stress im Pflegealltag?","a":"Pausen einhalten, Aufgaben priorisieren, im Team um Hilfe bitten, Grenzen setzen und Nein sagen, Ausgleich durch Bewegung und Schlaf, Gespräche mit Kolleginnen und Anleitung, Fortbildungen nutzen.","kw":"Pausen|pause; priorisieren|prioris; Team|team; Hilfe|hilfe; Grenzen|grenze; Bewegung|bewegung; Schlaf|schlaf"}]};
